1	/**
2	 * Feature Branch Lifecycle Manager (T8).
3	 *
4	 * Runs at orchestrator start, before the main dispatch loop.
5	 * Creates or syncs `feature/{featureId}` on the management (workspace) repo,
6	 * then records `feature_branch` and `feature_branch_base_sha` in status.yaml.
7	 *
8	 * Idempotent: safe to call on every restart. Never overwrites
9	 * `feature_branch_base_sha` once it is set — the drift daemon uses it
10	 * as its comparison baseline.
11	 *
12	 * Git operations are performed in the management repo (workspaceRoot).
13	 */
14	
15	import { execSync } from "node:child_process";
16	import { type Dirent, existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
17	import { join } from "node:path";
18	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
19	import { buildGitEnv } from "../git-env.js";
20	import {
21	  featureBranchName,
22	  statusYamlAbsPath,
23	  statusYamlRelPath,
24	} from "../paths.js";
25	import { curlJson } from "../utils/curl-json.js";
26	
27	// ── Types ─────────────────────────────────────────────────────────────────────
28	
29	export interface EnsureFeatureBranchOpts {
30	  /** Absolute path to the management (workspace) repo. */
31	  workspaceRoot: string;
32	  /** Feature directory ID, e.g. "autonomous-task-orchestrator". */
33	  featureId: string;
34	  /** Base branch declared for the management repo in workspace.yaml. */
35	  baseBranch: string;
36	  gitAuthorEmail: string;
37	  gitAuthorName: string;
38	  sshKeyPath?: string;
39	  /** When provided, opens a draft PR on first branch creation. Idempotent — skipped if status.yaml.handoff_pr_url is already set. */
40	  githubToken?: string;
41	  repoOwner?: string;
42	  repoName?: string;
43	  emit: (event: Record<string, unknown>) => void;
44	}
45	
46	export interface EnsureFeatureBranchResult {
47	  /** The feature branch name, e.g. "feature/autonomous-task-orchestrator". */
48	  featureBranch: string;
49	  /** Whether the branch was created fresh (true) or already existed (false). */
50	  created: boolean;
51	}
52	
53	// ── Helpers ───────────────────────────────────────────────────────────────────
54	
55	interface StatusYaml {
56	  feature_branch?: string | null;
57	  feature_branch_base_sha?: string | null;
58	  handoff_pr_url?: string | null;
59	  [key: string]: unknown;
60	}
61	
62	function execGit(cmd: string, env: NodeJS.ProcessEnv, cwd: string): string {
63	  return execSync(cmd, {
64	    cwd,
65	    env,
66	    encoding: "utf-8",
67	    stdio: "pipe",
68	    timeout: 60_000,
69	  }).trim();
70	}
71	
72	/**
73	 * Returns true if `refs/heads/<branch>` exists on the remote.
74	 * Uses `git ls-remote --exit-code` — exit code 2 means not found.
75	 */
76	function remoteHasBranch(branch: string, env: NodeJS.ProcessEnv, cwd: string): boolean {
77	  try {
78	    execSync(`git ls-remote --exit-code origin "refs/heads/${branch}"`, {
79	      cwd,
80	      env,
81	      encoding: "utf-8",
82	      stdio: "pipe",
83	      timeout: 30_000,
84	    });
85	    return true;
86	  } catch {
87	    return false;
88	  }
89	}
90	
91	// ── Public API ────────────────────────────────────────────────────────────────
92	
93	/**
94	 * Ensure the feature branch exists and is synced with origin.
95	 * Updates status.yaml with `feature_branch` and `feature_branch_base_sha`
96	 * (writes only if unset; never overwrites `feature_branch_base_sha`).
97	 */
98	export function ensureFeatureBranch(
99	  opts: EnsureFeatureBranchOpts,
100	): EnsureFeatureBranchResult {
101	  const {
102	    workspaceRoot,
103	    featureId,
104	    baseBranch,
105	    gitAuthorEmail,
106	    gitAuthorName,
107	    sshKeyPath,
108	    githubToken,
109	    repoOwner,
110	    repoName,
111	    emit,
112	  } = opts;
113	
114	  const featureBranch = featureBranchName(featureId);
115	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
116	
117	  // ── Step 1: Fetch origin ──────────────────────────────────────────────────
118	  execGit("git fetch origin", env, workspaceRoot);
119	
120	  // ── Step 2: Check if feature branch exists on remote ──────────────────────
121	  const existsOnRemote = remoteHasBranch(featureBranch, env, workspaceRoot);
122	
123	  let baseSha: string;
124	  let created: boolean;
125	
126	  if (existsOnRemote) {
127	    // ── Branch already exists — checkout and sync ─────────────────────────
128	    try {
129	      // -B resets the local branch to origin's tip if it already exists locally,
130	      // or creates it fresh. This handles both clean and diverged local states.
131	      execGit(
132	        `git checkout -B "${featureBranch}" "origin/${featureBranch}"`,
133	        env,
134	        workspaceRoot,
135	      );
136	    } catch (checkoutErr) {
137	      // Checkout failed (e.g. working tree dirty — should not happen in orchestrator
138	      // context, but handle defensively by re-checkout from a clean base).
139	      emit({
140	        type: "feature_branch_checkout_error",
141	        feature_id: featureId,
142	        details: String(checkoutErr),
143	        action: "recovering_from_base",
144	      });
145	      execGit(`git checkout "${baseBranch}"`, env, workspaceRoot);
146	      try {
147	        execGit(`git branch -D "${featureBranch}"`, env, workspaceRoot);
148	      } catch {
149	        // Branch may not exist locally yet — ignore.
150	      }
151	      execGit(
152	        `git checkout -b "${featureBranch}" "origin/${featureBranch}"`,
153	        env,
154	        workspaceRoot,
155	      );
156	    }
157	
158	    // Compute merge-base — used when status.yaml has no feature_branch_base_sha.
159	    // git merge-base returns the common ancestor of the feature branch and origin base.
160	    try {
161	      baseSha = execGit(
162	        `git merge-base "${featureBranch}" "origin/${baseBranch}"`,
163	        env,
164	        workspaceRoot,
165	      );
166	    } catch {
167	      // Fallback: use the first commit on the feature branch relative to base.
168	      baseSha = execGit(
169	        `git rev-parse "origin/${baseBranch}"`,
170	        env,
171	        workspaceRoot,
172	      );
173	    }
174	
175	    created = false;
176	    emit({
177	      type: "feature_branch_synced",
178	      feature_id: featureId,
179	      branch: featureBranch,
180	    });
181	  } else {
182	    // ── Branch does not exist — create from base branch tip ───────────────
183	    execGit(`git checkout "${baseBranch}"`, env, workspaceRoot);
184	    execGit(`git pull origin "${baseBranch}"`, env, workspaceRoot);
185	    baseSha = execGit("git rev-parse HEAD", env, workspaceRoot);
186	
187	    // Use -B (reset) instead of -b (create-only) so a stale local branch from a
188	    // previous failed run is reset to base-branch tip rather than causing a fatal.
189	    execGit(`git checkout -B "${featureBranch}"`, env, workspaceRoot);
190	    execGit(`git push -u origin "${featureBranch}"`, env, workspaceRoot);
191	
192	    created = true;
193	    emit({
194	      type: "feature_branch_created",
195	      feature_id: featureId,
196	      branch: featureBranch,
197	      base_sha: baseSha,
198	    });
199	  }
200	
201	  // ── Step 3: Update status.yaml (only when fields are unset) ──────────────
202	  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
203	  if (!existsSync(statusPath)) {
204	    emit({
205	      type: "feature_status_yaml_not_found",
206	      feature_id: featureId,
207	      path: statusPath,
208	    });
209	    return { featureBranch, created };
210	  }
211	
212	  const statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
213	
214	  let changed = false;
215	  if (!statusYaml.feature_branch) {
216	    statusYaml.feature_branch = featureBranch;
217	    changed = true;
218	  }
219	  // Never overwrite feature_branch_base_sha — it is the drift baseline.
220	  if (!statusYaml.feature_branch_base_sha) {
221	    statusYaml.feature_branch_base_sha = baseSha;
222	    changed = true;
223	  }
224	
225	  if (changed) {
226	    writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");
227	
228	    const relPath = statusYamlRelPath(featureId);
229	    execGit(`git add "${relPath}"`, env, workspaceRoot);
230	    try {
231	      execGit(
232	        `git commit -m "chore(${featureId}): record feature branch metadata in status.yaml"`,
233	        env,
234	        workspaceRoot,
235	      );
236	      execGit(`git push origin "${featureBranch}"`, env, workspaceRoot);
237	    } catch (commitErr) {
238	      const stderr = (commitErr as { stderr?: string }).stderr ?? "";
239	      if (!stderr.includes("nothing to commit")) {
240	        throw commitErr;
241	      }
242	      // Nothing to commit — status.yaml already had correct values. Continue.
243	    }
244	
245	    emit({
246	      type: "feature_branch_status_updated",
247	      feature_id: featureId,
248	      branch: featureBranch,
249	      fields_written: Object.keys(statusYaml).filter(
250	        (k) => k === "feature_branch" || k === "feature_branch_base_sha",
251	      ),
252	    });
253	  }
254	
255	  // ── Step 4: Open draft PR on first creation (idempotent) ─────────────────
256	  // Skip if handoff_pr_url is already recorded — PR was opened on a prior run.
257	  if (githubToken && repoOwner && repoName && !statusYaml.handoff_pr_url) {
258	    try {
259	      const createUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls`;
260	      const response = curlJson([
261	        "-s", "-X", "POST",
262	        "-H", `Authorization: token ${githubToken}`,
263	        "-H", "Accept: application/vnd.github+json",
264	        "-H", "Content-Type: application/json",
265	        "-d", JSON.stringify({
266	          title: `feat(${featureId}): feature branch — work in progress`,
267	          body: `Feature \`${featureId}\` is under development. This draft PR tracks progress on the feature branch. It will be promoted to ready-for-review at handoff.`,
268	          head: featureBranch,
269	          base: baseBranch,
270	          draft: true,
271	        }),
272	        createUrl,
273	      ]) as { html_url?: string };
274	
275	      if (response.html_url) {
276	        statusYaml.handoff_pr_url = response.html_url;
277	        writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");
278	
279	        const relPath = statusYamlRelPath(featureId);
280	        execGit(`git add "${relPath}"`, env, workspaceRoot);
281	        try {
