1	/**
2	 * Unit tests for T8+T9: Feature Branch Lifecycle Manager.
3	 *
4	 * Tests cover:
5	 *   1. Fresh start — feature branch doesn't exist → creates branch + writes status.yaml
6	 *   2. Restart — branch exists, clean sync → resets to origin tip
7	 *   3. Force-push recovery — checkout -B handles diverged local branch transparently
8	 *   4. status.yaml: feature_branch_base_sha never overwritten once set
9	 *   5. status.yaml absent → emits event and returns without error
10	 *   6. runFeatureBranchLifecycle: scans features, skips missing status.yaml
11	 *   7. Draft PR opened on first branch creation when githubToken provided
12	 *   8. Draft PR skipped on restart when handoff_pr_url already set (idempotent)
13	 *   9. Draft PR skipped with event when githubToken absent
14	 */
15	
16	import { describe, it, expect, vi, afterEach } from "vitest";
17	
18	vi.mock("../src/utils/curl-json.js", () => ({ curlJson: vi.fn() }));
19	import {
20	  mkdtempSync,
21	  mkdirSync,
22	  writeFileSync,
23	  readFileSync,
24	  rmSync,
25	} from "node:fs";
26	import { join } from "node:path";
27	import { tmpdir } from "node:os";
28	import { execSync } from "node:child_process";
29	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
30	import { ensureFeatureBranch, runFeatureBranchLifecycle } from "../src/feature-branch/lifecycle-manager.js";
31	
32	// ── Git helpers ───────────────────────────────────────────────────────────────
33	
34	function git(cmd: string, cwd: string): string {
35	  return execSync(cmd, {
36	    cwd,
37	    encoding: "utf-8",
38	    stdio: "pipe",
39	    env: {
40	      ...process.env,
41	      GIT_AUTHOR_NAME: "test",
42	      GIT_AUTHOR_EMAIL: "test@test.com",
43	      GIT_COMMITTER_NAME: "test",
44	      GIT_COMMITTER_EMAIL: "test@test.com",
45	    },
46	  }).trim();
47	}
48	
49	/**
50	 * Creates a bare remote repo and a local clone that simulates the management repo.
51	 * Returns { remote, local }.
52	 */
53	function makeGitPair(baseDir: string): { remote: string; local: string } {
54	  const remote = join(baseDir, "remote.git");
55	  const local = join(baseDir, "local");
56	
57	  mkdirSync(remote);
58	  mkdirSync(local);
59	
60	  // Init bare remote
61	  git("git init --bare", remote);
62	
63	  // Init local with initial commit on 'main' branch
64	  git("git init -b main", local);
65	  git("git config user.email test@test.com", local);
66	  git("git config user.name test", local);
67	  writeFileSync(join(local, "README.md"), "hello");
68	  git("git add README.md", local);
69	  git("git commit -m 'init'", local);
70	  git(`git remote add origin file://${remote}`, local);
71	  git("git push -u origin main", local);
72	  git("git fetch origin", local);
73	
74	  return { remote, local };
75	}
76	
77	/**
78	 * Write a minimal status.yaml under docs/features/{featureId}/ in the workspace.
79	 */
80	function writeStatusYaml(
81	  workspaceRoot: string,
82	  featureId: string,
83	  extra: Record<string, unknown> = {},
84	): void {
85	  const dir = join(workspaceRoot, "docs", "features", featureId);
86	  mkdirSync(dir, { recursive: true });
87	  const yaml: Record<string, unknown> = {
88	    feature_id: featureId,
89	    feature_status: "ready_for_implementation",
90	    ...extra,
91	  };
92	  writeFileSync(join(dir, "status.yaml"), yamlStringify(yaml));
93	}
94	
95	function commitAll(cwd: string, msg: string): void {
96	  git("git add -A", cwd);
97	  try {
98	    git(`git commit -m "${msg}"`, cwd);
99	  } catch {
100	    // nothing to commit — ok
101	  }
102	}
103	
104	// ── Temp directory tracking ───────────────────────────────────────────────────
105	
