107	
108	function trackDir(dir: string): string {
109	  tmpDirs.push(dir);
110	  return dir;
111	}
112	
113	afterEach(() => {
114	  for (const dir of tmpDirs.splice(0)) {
115	    try { rmSync(dir, { recursive: true, force: true }); } catch { /* ignore */ }
116	  }
117	});
118	
119	// ── Tests ─────────────────────────────────────────────────────────────────────
120	
121	const FEATURE_ID = "my-feature";
122	const BASE_BRANCH = "main";
123	
124	describe("ensureFeatureBranch", () => {
125	  const events: Record<string, unknown>[] = [];
126	  const emit = (e: Record<string, unknown>) => events.push(e);
127	
128	  afterEach(() => events.splice(0));
129	
130	  function makeOpts(local: string): Parameters<typeof ensureFeatureBranch>[0] {
131	    return {
132	      workspaceRoot: local,
