142	  it("fresh start — creates feature branch and writes status.yaml fields", () => {
143	    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-fresh-")));
144	    const { local } = makeGitPair(base);
145	
146	    writeStatusYaml(local, FEATURE_ID);
147	    commitAll(local, "add status.yaml");
148	    git("git push origin main", local);
149	
150	    const result = ensureFeatureBranch(makeOpts(local));
151	
152	    expect(result.featureBranch).toBe(`feature/${FEATURE_ID}`);
153	    expect(result.created).toBe(true);
