  it("branch deleted mid-session — recreated on next runFeatureBranchLifecycle call", () => {
    // Simulates a feature branch being merged+deleted while the orchestrator is
    // running. The next poll cycle calls runFeatureBranchLifecycle which must
    // recreate the branch from the base branch tip.
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-deleted-")));
    const { local } = makeGitPair(base);

    writeStatusYaml(local, "feature-deleted", { feature_status: "in_implementation" });
    commitAll(local, "add status.yaml");
    git("git push origin main", local);

    // First call — creates the branch.
    runFeatureBranchLifecycle({
      workspaceRoot: local,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      sshKeyPath: undefined,
      emit,
    });
    const created = events.filter((e) => e.type === "feature_branch_created");
    expect(created.length).toBe(1);

    // Simulate branch deletion (e.g. workspace PR merged + branch deleted).
    git("git push origin --delete feature/feature-deleted", local);
    // Verify it is gone from remote.
    const remoteAfterDelete = git("git ls-remote --heads origin", local);
    expect(remoteAfterDelete).not.toContain("feature/feature-deleted");

    events.splice(0);

    // Second call (simulating the next poll cycle) — must recreate the branch.
    runFeatureBranchLifecycle({
      workspaceRoot: local,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      sshKeyPath: undefined,
      emit,
    });

    const recreated = events.filter((e) => e.type === "feature_branch_created");
    expect(recreated.length).toBe(1);
    expect(recreated[0].feature_id).toBe("feature-deleted");

    // Branch must now exist on remote again.
    const remoteAfterRecreate = git("git ls-remote --heads origin", local);
    expect(remoteAfterRecreate).toContain("feature/feature-deleted");
  });

  it("branch already present — second call is a no-op (synced, not created)", () => {
    // Simulates steady-state: the poll cycle runs every 30s and the feature branch
    // already exists. runFeatureBranchLifecycle must not push or recreate anything.
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-noop-")));
    const { local } = makeGitPair(base);

    writeStatusYaml(local, "feature-stable", { feature_status: "in_implementation" });
    commitAll(local, "add status.yaml");
    git("git push origin main", local);

    // First call — creates the branch.
    runFeatureBranchLifecycle({
      workspaceRoot: local,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      sshKeyPath: undefined,
      emit,
    });
    expect(events.some((e) => e.type === "feature_branch_created")).toBe(true);
