tool_use_result.originalFile:
/**
 * Unit tests for T8+T9: Feature Branch Lifecycle Manager.
 *
 * Tests cover:
 *   1. Fresh start — feature branch doesn't exist → creates branch + writes status.yaml
 *   2. Restart — branch exists, clean sync → resets to origin tip
 *   3. Force-push recovery — checkout -B handles diverged local branch transparently
 *   4. status.yaml: feature_branch_base_sha never overwritten once set
 *   5. status.yaml absent → emits event and returns without error
 *   6. runFeatureBranchLifecycle: scans features, skips missing status.yaml
 *   7. Draft PR opened on first branch creation when githubToken provided
 *   8. Draft PR skipped on restart when handoff_pr_url already set (idempotent)
 *   9. Draft PR skipped with event when githubToken absent
 */

import { describe, it, expect, vi, afterEach } from "vitest";

vi.mock("../src/utils/curl-json.js", () => ({ curlJson: vi.fn() }));
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { execSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { ensureFeatureBranch, runFeatureBranchLifecycle } from "../src/feature-branch/lifecycle-manager.js";

// ── Git helpers ───────────────────────────────────────────────────────────────

function git(cmd: string, cwd: string): string {
  return execSync(cmd, {
    cwd,
    encoding: "utf-8",
    stdio: "pipe",
    env: {
      ...process.env,
      GIT_AUTHOR_NAME: "test",
      GIT_AUTHOR_EMAIL: "test@test.com",
      GIT_COMMITTER_NAME: "test",
      GIT_COMMITTER_EMAIL: "test@test.com",
    },
  }).trim();
}

/**
 * Creates a bare remote repo and a local clone that simulates the management repo.
 * Returns { remote, local }.
 */
function makeGitPair(baseDir: string): { remote: string; local: string } {
  const remote = join(baseDir, "remote.git");
  const local = join(baseDir, "local");

  mkdirSync(remote);
  mkdirSync(local);

  // Init bare remote
  git("git init --bare", remote);

  // Init local with initial commit on 'main' branch
  git("git init -b main", local);
  git("git config user.email test@test.com", local);
  git("git config user.name test", local);
  writeFileSync(join(local, "README.md"), "hello");
  git("git add README.md", local);
  git("git commit -m 'init'", local);
  git(`git remote add origin file://${remote}`, local);
  git("git push -u origin main", local);
  git("git fetch origin", local);

  return { remote, local };
}

/**
 * Write a minimal status.yaml under docs/features/{featureId}/ in the workspace.
 */
function writeStatusYaml(
  workspaceRoot: string,
  featureId: string,
  extra: Record<string, unknown> = {},
): void {
  const dir = join(workspaceRoot, "docs", "features", featureId);
  mkdirSync(dir, { recursive: true });
  const yaml: Record<string, unknown> = {
    feature_id: featureId,
    feature_status: "ready_for_implementation",
    ...extra,
  };
  writeFileSync(join(dir, "status.yaml"), yamlStringify(yaml));
}

function commitAll(cwd: string, msg: string): void {
  git("git add -A", cwd);
  try {
    git(`git commit -m "${msg}"`, cwd);
  } catch {
    // nothing to commit — ok
  }
}

// ── Temp directory tracking ───────────────────────────────────────────────────

const tmpDirs: string[] = [];

function trackDir(dir: string): string {
  tmpDirs.push(dir);
  return dir;
}

afterEach(() => {
  for (const dir of tmpDirs.splice(0)) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* ignore */ }
  }
});

// ── Tests ─────────────────────────────────────────────────────────────────────

const FEATURE_ID = "my-feature";
const BASE_BRANCH = "main";

describe("ensureFeatureBranch", () => {
  const events: Record<string, unknown>[] = [];
  const emit = (e: Record<string, unknown>) => events.push(e);

  afterEach(() => events.splice(0));

  function makeOpts(local: string): Parameters<typeof ensureFeatureBranch>[0] {
    return {
      workspaceRoot: local,
      featureId: FEATURE_ID,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      sshKeyPath: undefined,
      emit,
    };
  }

  it("fresh start — creates feature branch and writes status.yaml fields", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-fresh-")));
    const { local } = makeGitPair(base);

    writeStatusYaml(local, FEATURE_ID);
    commitAll(local, "add status.yaml");
    git("git push origin main", local);

    const result = ensureFeatureBranch(makeOpts(local));

    expect(result.featureBranch).toBe(`feature/${FEATURE_ID}`);
    expect(result.created).toBe(true);

    // Verify feature branch was pushed to remote
    const branches = git("git ls-remote --heads origin", local);
    expect(branches).toContain(`feature/${FEATURE_ID}`);

    // Verify status.yaml was updated
    const statusYaml = parseYaml(
      readFileSync(join(local, "docs", "features", FEATURE_ID, "status.yaml"), "utf-8"),
    ) as Record<string, unknown>;
    expect(statusYaml.feature_branch).toBe(`feature/${FEATURE_ID}`);
    expect(typeof statusYaml.feature_branch_base_sha).toBe("string");
    expect((statusYaml.feature_branch_base_sha as string).length).toBe(40);

    // Verify feature_branch_created event was emitted
    expect(events.some((e) => e.type === "feature_branch_created")).toBe(true);
  });

  it("restart — branch exists, syncs to origin tip", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-restart-")));
    const { local } = makeGitPair(base);

    writeStatusYaml(local, FEATURE_ID);
    commitAll(local, "add status.yaml");
    git("git push origin main", local);

    // First run — creates branch
    ensureFeatureBranch(makeOpts(local));

    // Add a commit on the feature branch from a different clone
    // (simulate another agent pushing to the feature branch)
    const base2 = trackDir(mkdtempSync(join(tmpdir(), "lcm-second-clone-")));
    const local2 = join(base2, "clone2");
    mkdirSync(local2);
    git(`git clone file://${join(base, "remote.git")} ${local2}`, tmpdir());
    git("git config user.email test2@test.com", local2);
    git("git config user.name test2", local2);
    git(`git checkout feature/${FEATURE_ID}`, local2);
    writeFileSync(join(local2, "extra.txt"), "from second clone");
    git("git add extra.txt", local2);
    git("git commit -m 'extra commit from second clone'", local2);
    git(`git push origin feature/${FEATURE_ID}`, local2);

    events.splice(0);

    // Second run — should sync without error
    const result2 = ensureFeatureBranch(makeOpts(local));
    expect(result2.created).toBe(false);
    expect(events.some((e) => e.type === "feature_branch_synced")).toBe(true);

    // Verify local branch has the new commit
    const log = git(`git log --oneline feature/${FEATURE_ID}`, local);
    expect(log).toContain("extra commit from second clone");
  });

  it("force-push recovery — checkout -B resets local to origin tip after diverge", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-fp-")));
    const { local } = makeGitPair(base);

    writeStatusYaml(local, FEATURE_ID);
    commitAll(local, "add status.yaml");
    git("git push origin main", local);

    // First run — creates feature branch
    ensureFeatureBranch(makeOpts(local));

    // Simulate a diverged local: advance local feature branch with a local-only commit
    git(`git checkout feature/${FEATURE_ID}`, local);
    writeFileSync(join(local, "local-only.txt"), "this commit is only local");
    git("git add local-only.txt", local);
    git("git commit -m 'local-only commit (diverged)'", local);

    // Simulate a force-push on the remote: reset origin feature branch to the main tip
    // (does NOT include the local-only commit)
    const remoteMainSha = git("git rev-parse origin/main", local);
    git(`git push origin ${remoteMainSha}:refs/heads/feature/${FEATURE_ID} --force`, local);

    // Verify local branch is diverged from origin
    const localSha = git(`git rev-parse feature/${FEATURE_ID}`, local);
    const remoteShaRaw = git(`git ls-remote origin refs/heads/feature/${FEATURE_ID}`, local);
    const remoteSha = remoteShaRaw.split(/\s/)[0];
    expect(localSha).not.toBe(remoteSha);

    events.splice(0);
    // Return to main so ensureFeatureBranch can do a clean checkout
    git("git checkout main", local);

    // Second run — should reset local branch to origin tip without error
    const result2 = ensureFeatureBranch(makeOpts(local));
    expect(result2.created).toBe(false);

    // Local branch should now match origin (force-push recovery)
    const localShaAfter = git(`git rev-parse feature/${FEATURE_ID}`, local);
    const remoteShaAfterRaw = git(`git ls-remote origin refs/heads/feature/${FEATURE_ID}`, local);
    const remoteShaAfter = remoteShaAfterRaw.split(/\s/)[0];
    expect(localShaAfter).toBe(remoteShaAfter);

    // local-only commit should NOT be present
    const log = git(`git log --oneline feature/${FEATURE_ID}`, local);
    expect(log).not.toContain("local-only commit (diverged)");
  });

  it("feature_branch_base_sha is never overwritten once set", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-no-overwrite-")));
    const { local } = makeGitPair(base);

    const existingBaseSha = "a".repeat(40);
    writeStatusYaml(local, FEATURE_ID, {
      feature_branch: `feature/${FEATURE_ID}`,
      feature_branch_base_sha: existingBaseSha,
    });
    commitAll(local, "add status.yaml with existing sha");
    git("git push origin main", local);

    ensureFeatureBranch(makeOpts(local));

    const statusYaml = parseYaml(
      readFileSync(join(local, "docs", "features", FEATURE_ID, "status.yaml"), "utf-8"),
    ) as Record<string, unknown>;

    // The existing SHA must not be overwritten
    expect(statusYaml.feature_branch_base_sha).toBe(existingBaseSha);
  });

  it("status.yaml absent — emits event and returns without error", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-no-status-")));
    const { local } = makeGitPair(base);

    // Do NOT create status.yaml
    const result = ensureFeatureBranch(makeOpts(local));

    expect(result.featureBranch).toBe(`feature/${FEATURE_ID}`);
    expect(events.some((e) => e.type === "feature_status_yaml_not_found")).toBe(true);
  });

  it("both feature_branch and feature_branch_base_sha already set — no status.yaml commit", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-already-set-")));
    const { local } = makeGitPair(base);

    const featureBranch = `feature/${FEATURE_ID}`;
    const sha = "b".repeat(40);
    writeStatusYaml(local, FEATURE_ID, {
      feature_branch: featureBranch,
      feature_branch_base_sha: sha,
    });
    commitAll(local, "add status.yaml with all fields set");
    git("git push origin main", local);

    ensureFeatureBranch(makeOpts(local));

    // No feature_branch_status_updated event should be emitted (no change)
    expect(events.some((e) => e.type === "feature_branch_status_updated")).toBe(false);
  });
});

describe("runFeatureBranchLifecycle", () => {
  const events: Record<string, unknown>[] = [];
  const emit = (e: Record<string, unknown>) => events.push(e);

  afterEach(() => events.splice(0));

  it("scans multiple features and processes each with a status.yaml", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-multi-")));
    const { local } = makeGitPair(base);

    writeStatusYaml(local, "feature-alpha");
    writeStatusYaml(local, "feature-beta");
    // feature-gamma has no status.yaml — should be skipped
    mkdirSync(join(local, "docs", "features", "feature-gamma"), { recursive: true });

    commitAll(local, "add features");
    git("git push origin main", local);

    runFeatureBranchLifecycle({
      workspaceRoot: local,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      sshKeyPath: undefined,
      emit,
    });

    const createdEvents = events.filter((e) => e.type === "feature_branch_created");
    expect(createdEvents.length).toBe(2);
    const featureIds = createdEvents.map((e) => e.feature_id as string);
    expect(featureIds).toContain("feature-alpha");
    expect(featureIds).toContain("feature-beta");
    expect(featureIds).not.toContain("feature-gamma");
  });

  it("workspace with no docs/features dir — emits event without error", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-empty-ws-")));
    const { local } = makeGitPair(base);

    runFeatureBranchLifecycle({
      workspaceRoot: local,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      sshKeyPath: undefined,
      emit,
    });

    expect(events.some((e) => e.type === "feature_branch_lifecycle_no_features_dir")).toBe(true);
  });

  it("skips features with in_design or done status — no branch created", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-skip-status-")));
    const { local } = makeGitPair(base);

    // These should be skipped
    writeStatusYaml(local, "feature-design", { feature_status: "in_design" });
    writeStatusYaml(local, "feature-tdd", { feature_status: "in_tdd" });
    writeStatusYaml(local, "feature-done", { feature_status: "done" });
    writeStatusYaml(local, "feature-cancelled", { feature_status: "cancelled" });
    // This should be processed
    writeStatusYaml(local, "feature-ready", { feature_status: "ready_for_implementation" });

    commitAll(local, "add features");
    git("git push origin main", local);

    runFeatureBranchLifecycle({
      workspaceRoot: local,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      sshKeyPath: undefined,
      emit,
    });

    const createdIds = events
      .filter((e) => e.type === "feature_branch_created")
      .map((e) => e.feature_id as string);
    expect(createdIds).toEqual(["feature-ready"]);

    const skippedIds = events
      .filter((e) => e.type === "feature_branch_lifecycle_skipped")
      .map((e) => e.feature_id as string);
    expect(skippedIds).toContain("feature-design");
    expect(skippedIds).toContain("feature-tdd");
    expect(skippedIds).toContain("feature-done");
    expect(skippedIds).toContain("feature-cancelled");
  });

  it("processes in_implementation and in_handoff features", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-impl-handoff-")));
    const { local } = makeGitPair(base);

    writeStatusYaml(local, "feature-impl", { feature_status: "in_implementation" });
    writeStatusYaml(local, "feature-handoff", { feature_status: "in_handoff" });

    commitAll(local, "add features");
    git("git push origin main", local);

    runFeatureBranchLifecycle({
      workspaceRoot: local,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      sshKeyPath: undefined,
      emit,
    });

    const createdIds = events
      .filter((e) => e.type === "feature_branch_created")
      .map((e) => e.feature_id as string);
    expect(createdIds).toContain("feature-impl");
    expect(createdIds).toContain("feature-handoff");
  });
});

// ── Draft PR tests ────────────────────────────────────────────────────────────

describe("ensureFeatureBranch — draft PR on first creation", () => {
  const events: Record<string, unknown>[] = [];
  const emit = (e: Record<string, unknown>) => events.push(e);
  afterEach(() => {
    events.splice(0);
    vi.clearAllMocks();
  });

  it("opens a draft PR and writes handoff_pr_url to status.yaml when githubToken is provided", async () => {
    const { curlJson } = await import("../src/utils/curl-json.js");
    vi.mocked(curlJson).mockReturnValue({ html_url: "https://github.com/owner/repo/pull/1" });

    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-draft-pr-")));
    const { local } = makeGitPair(base);
    const featureId = "feature-x";
    writeStatusYaml(local, featureId);
    commitAll(local, "add status.yaml");
    git("git push origin main", local);

    ensureFeatureBranch({
      workspaceRoot: local,
      featureId,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      githubToken: "ghp_test",
      repoOwner: "owner",
      repoName: "repo",
      emit,
    });

    const statusPath = join(local, "docs", "features", featureId, "status.yaml");
    const statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as Record<string, unknown>;
    expect(statusYaml.handoff_pr_url).toBe("https://github.com/owner/repo/pull/1");
    expect(events.some((e) => e.type === "draft_pr_opened")).toBe(true);
  });

  it("skips draft PR creation when handoff_pr_url is already set (idempotent)", async () => {
    const { curlJson } = await import("../src/utils/curl-json.js");
    vi.mocked(curlJson).mockReturnValue({ html_url: "https://github.com/owner/repo/pull/1" });

    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-draft-pr-skip-")));
    const { local } = makeGitPair(base);
    const featureId = "feature-y";
    // status.yaml already has handoff_pr_url set
    writeStatusYaml(local, featureId, { handoff_pr_url: "https://github.com/owner/repo/pull/1" });
    commitAll(local, "add status.yaml");
    git("git push origin main", local);

    ensureFeatureBranch({
      workspaceRoot: local,
      featureId,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      githubToken: "ghp_test",
      repoOwner: "owner",
      repoName: "repo",
      emit,
    });

    // curlJson must NOT have been called — draft PR creation was skipped
    expect(vi.mocked(curlJson)).not.toHaveBeenCalled();
    expect(events.some((e) => e.type === "draft_pr_opened")).toBe(false);
  });

  it("emits draft_pr_skipped when githubToken is absent", () => {
    const base = trackDir(mkdtempSync(join(tmpdir(), "lcm-no-token-")));
    const { local } = makeGitPair(base);
    const featureId = "feature-z";
    writeStatusYaml(local, featureId);
    commitAll(local, "add status.yaml");
    git("git push origin main", local);

    ensureFeatureBranch({
      workspaceRoot: local,
      featureId,
      baseBranch: BASE_BRANCH,
      gitAuthorEmail: "test@test.com",
      gitAuthorName: "test",
      // no githubToken
      emit,
    });

    expect(events.some((e) => e.type === "draft_pr_skipped")).toBe(true);
    const skipEvent = events.find((e) => e.type === "draft_pr_skipped");
    expect(skipEvent?.reason).toBe("no_github_token");
  });
